#include "nonlinear_solver.hpp"
int main(int argc,char**argv){try{fs::path out=argc>1?argv[1]:"rollout_results";fs::create_directories(out);std::ofstream csv(out/"trajectories.csv");csv<<std::setprecision(16)<<"N,stiffness,mass_ratio,h,method,steps,expected_steps,complete,max_energy,max_primal,max_stationarity,position_rms,velocity_rms,reference_gap,evaluations,failed_evaluations\n";
 for(int N:{8,32})for(double k:{1.,10.})for(double h:{1./30,1./60})for(std::string method:{"full","reduced_exact","reduced_GN_polish"}){auto c=chain_case(N,k,10);State s=c.initial,ref=s,ref2=s;double E0=energy(c.model,s),E=std::max(1e-6,E0-minimum_energy(c.model)),maxE=0,maxP=0,maxS=0,sumx=0,sumv=0,gap=0;int eval=0,failed=0,done=0,steps=std::lround(1/h);std::ofstream trace(out/(std::to_string(N)+"_"+std::to_string(k)+"_"+std::to_string(h)+"_"+method+".csv"));trace<<std::setprecision(16)<<"t,energy_error,position_error,velocity_error,primal,stationarity,evaluations\n";
 for(int i=0;i<steps;++i){LiftedFull full(c.model,s,h,E);ScaledReduced p(full,1);Solve a;State next;if(method=="full"){a=solve(full,128,[](const V&,const Evaluation&e){return e.objective.H;});next=full.state(a.z);}else{bool gn=method=="reduced_GN_polish";a=solve(p,gn?64:128,[&](const V&q,const Evaluation&e){return gn?p.gauss_newton(q,e):e.objective.H;});if(gn&&!a.converged){auto first=a;a=solve(p,128-first.evaluations,[](const V&,const Evaluation&e){return e.objective.H;},&first.dual,&first.z);a.evaluations+=first.evaluations;}next=p.state(a.z);}if(!a.converged||!finite(next)){failed=a.evaluations;break;}ref=reference_step(c.model,ref,h,128);ref2=reference_step(c.model,ref2,h,256);gap=std::max(gap,(ref.x-ref2.x).norm()+(ref.v-ref2.v).norm()/std::sqrt(E));double xe=(next.x-ref2.x).squaredNorm()/N,ve=(next.v-ref2.v).squaredNorm()/N,ee=std::abs(energy(c.model,next)-E0)/E;sumx+=xe;sumv+=ve;maxE=std::max(maxE,ee);maxP=std::max(maxP,a.primal);maxS=std::max(maxS,a.dual_residual);eval+=a.evaluations;s=next;++done;trace<<(i+1)*h<<','<<ee<<','<<std::sqrt(xe)<<','<<std::sqrt(ve)<<','<<a.primal<<','<<a.dual_residual<<','<<a.evaluations<<'\n';}
 csv<<N<<','<<k<<",10,"<<h<<','<<method<<','<<done<<','<<steps<<','<<(done==steps)<<','<<maxE<<','<<maxP<<','<<maxS<<','<<(done?std::sqrt(sumx/done):NAN)<<','<<(done?std::sqrt(sumv/done):NAN)<<','<<gap<<','<<eval<<','<<failed<<'\n';csv.flush();std::cout<<N<<' '<<k<<' '<<h<<' '<<method<<' '<<done<<'/'<<steps<<std::endl;
 }return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
